def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    day = day_context['day']
    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive_opponents = []
    threatening_bids = []
    rich_alive = 0

    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)
            if opp.get('budget', 0) > 0:
                rich_alive += 1
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None and opp.get('budget', 0) > 0:
                threatening_bids.append(prev.get('bid', 0))

    if not alive_opponents or rich_alive == 0:
        if hp <= 2 or no_water_days >= 1:
            return float(min(budget, 35.0))
        return float(min(budget, 5.0))

    highest_prev = max(threatening_bids) if threatening_bids else 0.0
    avg_prev = sum(threatening_bids) / float(len(threatening_bids)) if threatening_bids else 0.0

    scarcity = (supply - MIN_SUPPLY) / float(MAX_SUPPLY - MIN_SUPPLY)
    scarcity = max(0.0, min(1.0, scarcity))

    urgent = hp <= 2 or no_water_days >= 2
    pressured = hp <= 4 or no_water_days >= 1

    if urgent:
        base = max(62.0, highest_prev + 2.0)
    elif pressured:
        if highest_prev >= 120:
            base = 58.0
        else:
            base = max(42.0, avg_prev + 3.0)
    else:
        if supply >= 22:
            base = 12.0
        elif supply >= 19:
            base = 22.0
        else:
            if highest_prev >= 120:
                base = 28.0
            elif highest_prev >= 70:
                base = highest_prev + 1.5
            else:
                base = 34.0

    if day >= 8:
        base += 8.0
    elif day >= 6:
        base += 4.0

    if scarcity < 0.3:
        base += 10.0
    elif scarcity > 0.7:
        base -= 6.0

    if budget < 40:
        base = min(base, budget)
    elif budget < 80 and not urgent:
        base = min(base, 45.0)

    if highest_prev >= 140 and not urgent and hp >= 5:
        base = min(base, 25.0)

    bid = max(0.0, min(float(budget), float(base)))
    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    # Alive opponents
    alive = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive.append((oid, o))

    # If no opponents alive, spend enough to satisfy requirement
    if not alive:
        return min(my_status['budget'], DAILY_SALARY * 0.4)

    # Extract yesterday bids (immediate reaction only)
    prev_bids = []
    for _, o in alive:
        prev = o.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            try:
                prev_bids.append(float(prev['bid']))
            except Exception:
                pass

    highest_prev_bid = max(prev_bids) if prev_bids else 0.0
    avg_prev_bid = sum(prev_bids) / float(len(prev_bids)) if prev_bids else 0.0

    # Supply pressure: less supply => more aggressive
    # supply is between 15 and 25; normalize to [0,1] where 0 is tight
    tightness = (MAX_SUPPLY - supply) / float(MAX_SUPPLY - MIN_SUPPLY) if MAX_SUPPLY > MIN_SUPPLY else 0.5

    # If Cindy-like behavior (very high yesterday) exists, avoid matching her full spend.
    # Instead, bid slightly above likely clearing price based on others, but cap by budget.
    # Use highest_prev_bid only to decide whether to ramp.
    ramp = 0.0
    if highest_prev_bid >= 0.9 * 150.0:
        ramp = 0.15
    elif highest_prev_bid >= 0.7 * 150.0:
        ramp = 0.10
    elif highest_prev_bid >= 0.5 * 150.0:
        ramp = 0.06

    # HP urgency
    hp = float(my_status['hp'])
    no_water_days = int(my_status['no_water_days'])
    hp_urgent = 0.0
    if hp <= 1.5:
        hp_urgent = 0.35
    elif hp <= 3.0:
        hp_urgent = 0.22
    elif hp <= 5.0:
        hp_urgent = 0.10

    # Base bid target: aim around mid of salary scaled by tightness and urgency
    base = DAILY_SALARY * (0.42 + 0.25 * tightness + hp_urgent + ramp)

    # If yesterday clearing seemed high (avg high), nudge upward
    if avg_prev_bid >= 120.0:
        base *= 1.08
    elif avg_prev_bid >= 80.0:
        base *= 1.04

    # Ensure we don't overspend early; but if supply is tight and I'm low HP, ramp more
    if tightness > 0.6 and hp <= 4.0:
        base *= 1.18
    if day >= 7 and hp <= 4.0:
        base *= 1.10

    # Hard caps to preserve budget
    budget = float(my_status['budget'])
    if budget <= 0:
        return 0.0

    # Never exceed a fraction of budget; maintain optionality
    max_fraction = 0.75
    bid = min(budget * max_fraction, base)

    # If bid too low, ensure at least a minimal attempt when hp is critical
    if hp <= 2.0 or no_water_days >= 2:
        bid = max(bid, DAILY_SALARY * 0.65)

    # Final clamp
    if bid < 0.0:
        bid = 0.0
    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    DAILY_SALARY = 80
    WATER_REQ = 7
    supply = day_context['supply']
    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        return min(my_status['budget'], 10.0)

    yesterday_bids = [o['previous_trace']['bid'] for o in alive_opponents if o.get('previous_trace') and o['previous_trace'].get('bid') is not None]

    if yesterday_bids:
        max_prev = max(yesterday_bids)
        if supply < 18:
            return min(my_status['budget'], max(max_prev + 2.0, DAILY_SALARY * 0.7))
        elif my_status['hp'] < 4:
            return min(my_status['budget'], max_prev + 1.0)
        else:
            return min(my_status['budget'], max(DAILY_SALARY * 0.3, max_prev * 0.5))

    return min(my_status['budget'], DAILY_SALARY * 0.4)
